blocks.code:
a:link    { color: #1d4ed8; }
a:visited { color: #6b21a8; }
a:hover   { text-decoration-thickness: 3px; }
a:active  { color: #dc2626; }

button {
  padding: 0.5rem 1rem;
  border: 2px solid #1d4ed8;
  background: white;
  color: #1d4ed8;
}

button:hover {
  background: #1d4ed8;
  color: white;
}

button:focus-visible {
  outline: 3px solid #f59e0b;
  outline-offset: 2px;
}

ul {
  padding: 0;
  list-style: none;
}

li {
  padding: 0.5rem;
}

li:nth-child(odd) {
  background: #eff6ff;      /* zebra stripes */
}

li:first-child {
  border-top: 2px solid #1d4ed8;
}

li:last-child {
  border-bottom: 2px solid #1d4ed8;
}

h2::before {
  content: "# ";
  color: #1d4ed8;
}

p::first-letter {
  font-size: 2em;
  font-weight: 700;
  float: left;
  line-height: 1;
  padding-right: 0.25rem;
}

li::marker {
  color: #1d4ed8;
  font-size: 1.2em;
}

::selection {
  background: #fde68a;
}
